INSERT INTO `popular_videos` (`id`, `bvid`, `aid`, `title`, `description`, `author`, `tname`, `cover_url`, `publish_date`, `duration`, `view_count`, `danmaku_count`, `reply_count`, `comment_count`, `favorite_count`, `coin_count`, `share_count`, `like_count`, `score`, `rcmd_reason`, `scraped_at`) VALUES (3628, 'BV1dyXqBaEE5', 116321438206681, '《崩坏：星穹铁道》动画短片：「Never Gonna Give You Up」', '「今天是全年唯一可以干这种事的日子！小灰毛，喜欢吗？」\n「今天真开心！」\n「我都干了些什么…」\n「…我能回家了吗？」\n \n音乐改编已经过原发行商和版权所有者授权。\n \n演唱：Lizzie Freeman\n \n原唱： Rick Astley\n作曲： Peter Alan Waterman / Matthew James Aitken / Michael Stock\n原出版商：Original Publisher: Sids Songs Ltd./ PW Ballads/ Mike Stock Publish', '帕姆的收藏夹', NULL, 'http://i0.hdslb.com/bfs/archive/2d077083cab8eb01d94b9353286fdd2ea00a52dd.jpg', '2026-04-01 18:00:00', 66, 3029795, 14936, 0, 14670, 141444, 142246, 85775, 382490, 0, NULL, '2026-04-03 22:48:17');
INSERT INTO `popular_videos` (`id`, `bvid`, `aid`, `title`, `description`, `author`, `tname`, `cover_url`, `publish_date`, `duration`, `view_count`, `danmaku_count`, `reply_count`, `comment_count`, `favorite_count`, `coin_count`, `share_count`, `like_count`, `score`, `rcmd_reason`, `scraped_at`) VALUES (3627, 'BV1gB9GBWENQ', 116324894248063, '【游戏人生第二季】自制！耗时两月用AI动画制作第1话，这次的四月不再缺席！', '感谢@冰儿要成为小说家  对剧情的讨论和校对\n警告：这真的不是愚人节玩笑！\n《游戏人生》第二季真的来了！\n4 月 1 日，由全体粉丝共同 “三连和关注众筹” 的自制续作，正式上线！\n你没看错，不是 PV，不是预告，不是切片，是正片！\n我们把对空白的执念，把那句 “赌上无限接近零，却不等于零的可能性”，做成了属于我们自己的第二季。\n迪斯博德的棋盘永不落幕，只要还有人相信，游戏就永远不会结束。\n向盟约宣誓！\n部分剧情根据动画节奏改编，欢迎弹幕评论区讨论！\n※郑重声明：本作为粉丝同人自制创作，非官方出品，谨以此', 'acg阿伦', NULL, 'http://i2.hdslb.com/bfs/archive/15883ca6f45cf9b3cc1152e9573e2e7a6b2eb12c.jpg', '2026-04-01 11:34:11', 1308, 387426, 689, 0, 2614, 21274, 28812, 9382, 37539, 0, NULL, '2026-04-03 22:48:17');
