INSERT INTO `popular_videos` (`id`, `bvid`, `aid`, `title`, `description`, `author`, `tname`, `cover_url`, `publish_date`, `duration`, `view_count`, `danmaku_count`, `reply_count`, `comment_count`, `favorite_count`, `coin_count`, `share_count`, `like_count`, `score`, `rcmd_reason`, `scraped_at`) VALUES (3597, 'BV13W9KBzE7N', 116339725307088, '“我回望绿洲寻你声音”洛天依原创曲《煌》【国乐季·琵琶篇】', '“大漠聆风，壁画听弦；一声琵琶，梦回千年。”\n【天依游学记·歌行国乐季】琵琶篇原创单曲《煌》\n以反弹琵琶为形，以敦煌古谱为魂，唱一曲大漠风沙里不灭的华章\n丝路古道深处，岁月与风沙无声剥落，却把乐声与色彩藏进了壁画之上\n手心的沙砾回响不尽，指尖的弦音穿越千年\n与天依一起，飞入壁画，聆听古老的弦音在今日，又能鸣奏出怎样的新声吧~\n \n作曲：Lovan\n作词：Lovan\n调教：莫米兔\n编曲：Lovan\n混音：郭子敬\n母带：郭子敬\n音乐监制:林星捷/TENKO\n特别感谢：敦煌文旅', '洛天依', NULL, 'http://i1.hdslb.com/bfs/archive/8a604e6cf67059d7b3efbb89104dd6e636121c5d.jpg', '2026-04-03 18:00:00', 216, 29297, 462, 0, 1023, 5149, 6014, 689, 10046, 0, NULL, '2026-04-03 22:48:17');
