INSERT INTO `popular_videos` (`id`, `bvid`, `aid`, `title`, `description`, `author`, `tname`, `cover_url`, `publish_date`, `duration`, `view_count`, `danmaku_count`, `reply_count`, `comment_count`, `favorite_count`, `coin_count`, `share_count`, `like_count`, `score`, `rcmd_reason`, `scraped_at`) VALUES (3587, 'BV1KwXLBQE77', 116305617227400, '“Cheems，你要逃出时间循环吗？”【大结局·完】', '“看下去吧，lucy。故事还没结束呢。”\n\n希望大家能够看到这期视频的最后。循环连载到这里就结束了。但我知道看到最后的时候，大家还会有不少的疑问，所以电影合集篇会在4月30号更新，到时候会有全新的剧情，以及会对之前的部分进行一些修改。\n谢谢大家一直以来的支持，真的是你们的支持才让这个故事做完了，这句话真不是我客套。我会在最后的合集篇里倾尽全力来制作的！', '清竹莫叶', NULL, 'http://i0.hdslb.com/bfs/archive/e5bdb2c5be633203b4acfd77f91b4db1b7fc3342.jpg', '2026-03-28 18:00:00', 2469, 942406, 1962, 0, 1962, 93376, 33198, 2639, 142274, 0, NULL, '2026-04-03 22:48:17');
INSERT INTO `popular_videos` (`id`, `bvid`, `aid`, `title`, `description`, `author`, `tname`, `cover_url`, `publish_date`, `duration`, `view_count`, `danmaku_count`, `reply_count`, `comment_count`, `favorite_count`, `coin_count`, `share_count`, `like_count`, `score`, `rcmd_reason`, `scraped_at`) VALUES (3586, 'BV1gV9TBKEc8', 116339188502916, '【五周年纪念/翻唱】《猫中毒》完整版PV/嘉然', '原唱：テゴマス(TegoMass)\n歌 ：嘉然\n————————————————\n中文歌词：\n松软柔顺的皮毛\n让人欲罢不能的肉球\n不像是世间的触感\n灵活的躯体\n在黑夜中放光的瞳孔\n绝不放过目标猎物的阻击手\n会捅破纸门 也会攀爬纱窗\n坏事做尽之后 你对我叫唤着\n肚子饿了的话 喵喵喵喵~喵~\n心情不好的话 吓吓吓吓--吓--\n对总是自由自在的猫咪神魂颠倒\n一直高贵冷艳的表情\n时刻保持着自己步调\n独自在被炉中发出叫声\n咕噜咕噜咕噜~\n明明容易感到寂寞却喜欢独来独往\n太过缠人的话 快看\n猫咪punch punpu', '嘉然今天吃什么', NULL, 'http://i0.hdslb.com/bfs/archive/9f303d2c6cf883c95d9758fc0ebe2e957de53267.jpg', '2026-04-03 18:30:00', 151, 143070, 1237, 0, 6457, 6860, 23996, 10138, 22990, 0, NULL, '2026-04-03 22:48:17');
