INSERT INTO `video_comment` (`comment_id`, `bvid`, `task_id`, `username`, `gender`, `text_type`, `content`, `normalized_content`, `sentiment_score`, `sentiment_confidence`, `sentiment_intensity`, `sentiment_source`, `sentiment_version`, `emotion_tags_json`, `aspect_details_json`, `sentiment_label`, `like_count`, `reply_count`, `aspect`, `publish_time`, `scraped_at`) VALUES (925714599926537743, 'BV1SZXNBYEdh', 'c22d2895-f470-4b98-af76-e2f574841c3b', '一定会好起来i', '保密', 'comment', '现在，我颤抖着双手写下这封求助信。\n我是小琪的妈妈，一名普通的外卖员。无论刮风下雨、多苦多累，只要想到孩子，我都能咬牙坚持下去。可我的孩子才一岁，就患上了重病，承受着连大人都难以忍受的痛苦，瘦的让人心疼[大哭][大哭]。那么小的身子，全身扎满针眼，每次看到孩子疼得大哭，我都心痛到晕厥。\n我已经倾尽所有，一遍又一遍向亲友求助借钱，可面对高昂的治疗费用，依旧远远不够。\n恳求各位好心人，拉我可怜的孩子一把，给他一线生机。', '现在，我颤抖着双手写下这封求助信。 我是小琪的妈妈，一名普通的外卖员。无论刮风下雨、多苦多累，只要想到孩子，我都能咬牙坚持下去。可我的孩子才一岁，就患上了重病，承受着连大人都难以忍受的痛苦，瘦的让人心疼[大哭][大哭]。那么小的身子，全身扎满针眼，每次看到孩子疼得大哭，我都心痛到晕厥。 我已经倾尽所有，一遍又一遍向亲友求助借钱，可面对高昂的治疗费用，依旧远远不够。 恳求各位好心人，拉我可怜的孩子一把，给他一线生机。', 0.5196, 0.8561, 'MEDIUM', 'transformer_comment_v1', 'comment-chinese-roberta-v2.0.0', '[\"moved\"]', '[{\"label\": \"NEGATIVE\", \"score\": -0.2257, \"aspect\": \"价格\", \"source\": \"hybrid_clause_pair_v2\", \"context\": \"一遍又一遍向亲友求助借钱\", \"version\": \"aspect-hybrid-v2.0.0\", \"confidence\": 0.6205, \"mention_count\": 1}, {\"label\": \"NEUTRAL\", \"score\": 0.1553, \"aspect\": \"口味\", \"source\": \"hybrid_clause_pair_v2\", \"context\": \"无论刮风下雨、多苦多累；承受着连大人都难以忍受的痛苦\", \"version\": \"aspect-hybrid-v2.0.0\", \"confidence\": 0.99, \"mention_count\": 2}]', 'POSITIVE', 1, 0, '口味', '2026-03-31 20:28:47', '2026-04-03 15:28:27');
