INSERT INTO `video_comment` (`comment_id`, `bvid`, `task_id`, `username`, `gender`, `text_type`, `content`, `normalized_content`, `sentiment_score`, `sentiment_confidence`, `sentiment_intensity`, `sentiment_source`, `sentiment_version`, `emotion_tags_json`, `aspect_details_json`, `sentiment_label`, `like_count`, `reply_count`, `aspect`, `publish_time`, `scraped_at`) VALUES (3115470309407847602, 'BV1SZXNBYEdh', 'c22d2895-f470-4b98-af76-e2f574841c3b', '坚持就会好起来', '保密', 'comment', '对不起，我的儿子。\n妈妈真的快要撑不住了。我只是一个普通的农村妈妈，没文化，只能做最底层的工作：凌晨当环卫工倒垃圾，白天在大排档洗碗。再苦再累，只要有小家在，我都觉得幸福。可六岁的儿子俊皓被确诊重疾后，我们的生活彻底陷入了绝境。\n看着孩子因为病痛再也没有笑容，做父母的心如刀绞。希望大家能看看我们，给孩子一句问候、一份鼓励，我们感激不尽。\n祝好人一生平安！', '对不起，我的儿子。 妈妈真的快要撑不住了。我只是一个普通的农村妈妈，没文化，只能做最底层的工作：凌晨当环卫工倒垃圾，白天在大排档洗碗。再苦再累，只要有小家在，我都觉得幸福。可六岁的儿子俊皓被确诊重疾后，我们的生活彻底陷入了绝境。 看着孩子因为病痛再也没有笑容，做父母的心如刀绞。希望大家能看看我们，给孩子一句问候、一份鼓励，我们感激不尽。 祝好人一生平安！', 0.3585, 0.8128, 'WEAK', 'transformer_comment_v1', 'comment-chinese-roberta-v2.0.0', '[\"amused\"]', '[{\"label\": \"NEUTRAL\", \"score\": -0.0837, \"aspect\": \"性能\", \"source\": \"hybrid_clause_pair_v2\", \"context\": \"妈妈真的快要撑不住了\", \"version\": \"aspect-hybrid-v2.0.0\", \"confidence\": 0.5604, \"mention_count\": 1}, {\"label\": \"NEUTRAL\", \"score\": 0.1505, \"aspect\": \"口味\", \"source\": \"hybrid_clause_pair_v2\", \"context\": \"再苦再累\", \"version\": \"aspect-hybrid-v2.0.0\", \"confidence\": 0.6095, \"mention_count\": 1}]', 'POSITIVE', 1, 0, '口味', '2026-03-31 23:39:11', '2026-04-03 15:28:26');
