INSERT INTO `video_comment` (`comment_id`, `bvid`, `task_id`, `username`, `gender`, `text_type`, `content`, `normalized_content`, `sentiment_score`, `sentiment_confidence`, `sentiment_intensity`, `sentiment_source`, `sentiment_version`, `emotion_tags_json`, `aspect_details_json`, `sentiment_label`, `like_count`, `reply_count`, `aspect`, `publish_time`, `scraped_at`) VALUES (5438589505488777268, 'BV1SZXNBYEdh', 'c22d2895-f470-4b98-af76-e2f574841c3b', '我相信一定会有希望E', '保密', 'comment', '对不起🙏🙏\n用这种方式打扰到大家真的很抱歉[保佑][保佑]\n我是一位普通军人父亲，家里6岁的孩子不幸患上重症，一直在接受治疗。化疗、穿刺一次次折磨着他，头发掉光了，视力也受到严重影响，从前活泼爱笑的孩子，现在只能虚弱地躺在病床上，每次看到都心如刀割。为给孩子治病，家里所有积蓄早已花光，能借的亲戚朋友都借遍了，早已负债累累。我白天黑夜连轴转，拼命打3份工赚钱，可面对后续高昂的治疗费用，依旧远远不够，实在已经走投无路。我真的不想放弃孩子，恳请各位好心人能帮帮我们，哪怕只是随手转发，也是孩子活下去的希望。真心谢谢每一位伸出援手的朋友，感谢🙏🏻大家[保佑][保佑][保佑]深深给大家敬礼！', '对不起🙏🙏 用这种方式打扰到大家真的很抱歉[保佑][保佑] 我是一位普通军人父亲，家里6岁的孩子不幸患上重症，一直在接受治疗。化疗、穿刺一次次折磨着他，头发掉光了，视力也受到严重影响，从前活泼爱笑的孩子，现在只能虚弱地躺在病床上，每次看到都心如刀割。为给孩子治病，家里所有积蓄早已花光，能借的亲戚朋友都借遍了，早已负债累累。我白天黑夜连轴转，拼命打3份工赚钱，可面对后续高昂的治疗费用，依旧远远不够，实在已经走投无路。我真的不想放弃孩子，恳请各位好心人能帮帮我们，哪怕只是随手转发，也是孩子活下去的希望。真心谢谢每一位伸出援手的朋友，感谢🙏🏻大家[保佑][保佑][保佑]深深给大家敬礼！', -0.1321, 0.5650, 'WEAK', 'transformer_comment_v1', 'comment-chinese-roberta-v2.0.0', '[\"amused\"]', '[{\"label\": \"NEUTRAL\", \"score\": -0.0292, \"aspect\": \"价格\", \"source\": \"hybrid_clause_pair_v2\", \"context\": \"拼命打3份工赚钱\", \"version\": \"aspect-hybrid-v2.0.0\", \"confidence\": 0.398, \"mention_count\": 1}]', 'NEUTRAL', 1, 0, '价格', '2026-04-02 20:30:11', '2026-04-03 15:28:24');
