INSERT INTO `video_comment` (`comment_id`, `bvid`, `task_id`, `username`, `gender`, `text_type`, `content`, `normalized_content`, `sentiment_score`, `sentiment_confidence`, `sentiment_intensity`, `sentiment_source`, `sentiment_version`, `emotion_tags_json`, `aspect_details_json`, `sentiment_label`, `like_count`, `reply_count`, `aspect`, `publish_time`, `scraped_at`) VALUES (6453665033548534378, 'BV1SZXNBYEdh', 'c22d2895-f470-4b98-af76-e2f574841c3b', '坚定坚定坚定', '保密', 'comment', '真的对不起，心里实在太难受了，我以前在边疆当过兵，那时候再苦再难我都自己扛，从来没跟别人开过口求过谁。现在我就是一个普通外卖员，每天拼命跑单，只想好好养家，可偏偏孩子出事了。我女儿烁烁今年才3岁，得了重病，我们在外地治病已经花光了所有钱，能借的都借了，能卖的也都卖了。医院一直催费，看着孩子遭罪、一天天瘦下去、头发掉完，我当爸的却一点办法都没有，心里特别难受。我真的不想放弃，孩子还这么小。实在走投无路，才鼓起勇气在这里跟大家说一声，希望有好心人能帮帮忙，拉烁烁一把。感恩不尽', '真的对不起，心里实在太难受了，我以前在边疆当过兵，那时候再苦再难我都自己扛，从来没跟别人开过口求过谁。现在我就是一个普通外卖员，每天拼命跑单，只想好好养家，可偏偏孩子出事了。我女儿烁烁今年才3岁，得了重病，我们在外地治病已经花光了所有钱，能借的都借了，能卖的也都卖了。医院一直催费，看着孩子遭罪、一天天瘦下去、头发掉完，我当爸的却一点办法都没有，心里特别难受。我真的不想放弃，孩子还这么小。实在走投无路，才鼓起勇气在这里跟大家说一声，希望有好心人能帮帮忙，拉烁烁一把。感恩不尽', -0.2140, 0.4814, 'WEAK', 'transformer_comment_v1', 'comment-chinese-roberta-v2.0.0', '[]', '[{\"label\": \"NEUTRAL\", \"score\": -0.1126, \"aspect\": \"价格\", \"source\": \"hybrid_clause_pair_v2\", \"context\": \"我们在外地治病已经花光了所有钱\", \"version\": \"aspect-hybrid-v2.0.0\", \"confidence\": 0.5361, \"mention_count\": 1}, {\"label\": \"POSITIVE\", \"score\": 0.3732, \"aspect\": \"口味\", \"source\": \"hybrid_clause_pair_v2\", \"context\": \"那时候再苦再难我都自己扛\", \"version\": \"aspect-hybrid-v2.0.0\", \"confidence\": 0.8486, \"mention_count\": 1}]', 'NEUTRAL', 1, 0, '口味', '2026-03-31 19:47:13', '2026-04-03 15:28:27');
